// == and != over a matrix of primitive (and a few object) pairs: the fast path's primitive table
// and the general operation (Vm::equal) read one table, so every tier answers as Node does.
const s = Symbol("s");
const values = () => [undefined, null, true, false, 0, -0, 1, NaN, Infinity, "", "0", "1", " 1 ", "abc", "1n", s, 0n, 1n, {}, [], [1], { valueOf() { return 1; } }];
const want = "";
function table() {
  const v = values(); let bits = "";
  for (let i = 0; i < v.length; i++) for (let j = 0; j < v.length; j++) bits += (v[i] == v[j] ? "1" : "0") + (v[i] != v[j] ? "1" : "0");
  return bits;
}
for (let round = 0; round < 300; round++) {
  const got = table();
  if (got !== want) {
    const at = [...got].findIndex((bit, k) => bit !== want[k]);
    throw new Error("round " + round + ": pair " + (at >> 1) + " differs");
  }
}
console.log("ok loose-equality");
